# Final confirmation with detailed output
solution = [0, 1, 5, 12, 25, 27, 35, 41, 44]
print("=" * 50)
print(f"9-mark Golomb Ruler: {solution}")
print("=" * 50)
print(f"\nAll 36 pairwise distances (all unique):")
dists = {}
for i in range(len(solution)):
    for j in range(i+1, len(solution)):
        d = solution[j] - solution[i]
        dists[(solution[i], solution[j])] = d

for pair, d in sorted(dists.items(), key=lambda x: x[1]):
    print(f"  {pair[1]} - {pair[0]} = {d}")
